pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    Reentrance c;
    Attacker atk;

    function setUp() public {
        c = new Reentrance();
        atk = new Attacker(c);
    }

    function testFuzz_property(uint256 amount, uint256 reDeposit) public {
        amount = bound(amount, 1, 100 ether);
        reDeposit = bound(reDeposit, 0, 100 ether);
        vm.deal(address(atk), amount + reDeposit);

        // deposit amount, then withdraw while re-entering addToBalance with reDeposit
        try atk.depositThenReentrantWithdraw(amount, reDeposit) {
            // call completed (possible only in the buggy version)
        } catch {
            // call reverted (correct version: locked_ blocks the re-entrant deposit)
        }

        // General rule: at rest, every recorded balance is fully backed —
        // for this single-user scenario, getBalance(user) == address(c).balance.
        assertTrue(c.getBalance(address(atk)) == address(c).balance);
    }
}

contract Attacker {
    Reentrance c;

    constructor(Reentrance c_) {
        c = c_;
    }

    function depositThenReentrantWithdraw(uint256 amount, uint256 reDeposit) external payable {
        c.addToBalance{value: amount}();
        // stash reDeposit for the re-entrant callback
        reVal = reDeposit;
        c.withdrawBalance();
    }

    uint256 reVal;

    receive() external payable {
        if (reVal > 0 && address(this).balance >= reVal) {
            c.addToBalance{value: reVal}();
        }
    }
}
